/* XivigAuth Input Icon, Toggle & Flex-Group Fixes */
.fauth-input-icon{left:15px;z-index:6}
.fauth-form .fauth-input-wrap .fauth-input-icon+.form-control,.fauth-form .fauth-input-wrap:has(.fauth-input-icon) .form-control{padding-left:44px}
.fauth-form .fauth-input-wrap-toggle .form-control{padding-right:46px}
.fauth-form .fauth-input-wrap-toggle .form-control.is-invalid{background-position:right 46px center;padding-right:74px}
.fauth-form input[type=password]::-ms-reveal,.fauth-form input[type=password]::-ms-clear{display:none}
.fauth-form .fauth-input-wrap-toggle .fauth-btn-toggle{position:absolute;top:50%;right:6px;transform:translateY(-50%);width:34px;height:34px;padding:0;margin:0;border:none;border-radius:8px;background:transparent;color:var(--muted-color);z-index:6;display:inline-flex;align-items:center;justify-content:center;font-size:1.05rem;cursor:pointer;transition:color var(--transition-fast),background-color var(--transition-fast)}
.fauth-form .fauth-input-wrap-toggle .fauth-btn-toggle:hover{color:var(--accent-color);background:#6366f114}
.fauth-form .fauth-input-wrap-toggle .fauth-btn-toggle:focus,.fauth-form .fauth-input-wrap-toggle .fauth-btn-toggle:focus-visible{outline:none;box-shadow:none}
[data-theme=dark] .fauth-form .fauth-input-wrap-toggle .fauth-btn-toggle{color:#94a3b8;background:transparent}
[data-theme=dark] .fauth-form .fauth-input-wrap-toggle .fauth-btn-toggle:hover{color:#a5b4fc;background:#818cf81f}
.fauth-form .input-group{width:100%;display:flex;flex-wrap:nowrap;align-items:stretch;position:relative}
.fauth-form .input-group>.fauth-input-wrap{flex:1 1 auto;width:1%;min-width:0}
.fauth-form .input-group .form-control{border-top-right-radius:0;border-bottom-right-radius:0}
.fauth-form .input-group .fauth-btn-toggle{flex:0 0 auto;width:auto;height:46px;padding:0 14px;margin-left:-1px;border:1px solid var(--border-color);border-radius:0 12px 12px 0;background:var(--input-bg);color:var(--muted-color);display:inline-flex;align-items:center;justify-content:center;font-size:1.05rem;cursor:pointer}
[data-theme=dark] .fauth-form .input-group .fauth-btn-toggle{background:#0a0f1eb3;border-color:#ffffff1a;color:#94a3b8}
/* XivigAdmin Header Logout & Active Notification Badge Fixes */
.user-menu-footer .user-menu-logout{width:100%;color:var(--danger-color);border:1px solid color-mix(in srgb,var(--danger-color),transparent 72%);border-radius:var(--radius-md);background:color-mix(in srgb,var(--danger-color),transparent 94%);justify-content:center;align-items:center;gap:6px;padding:8px 12px;font-size:.78rem;font-weight:700;text-decoration:none;display:flex;cursor:pointer;transition:background-color var(--transition-fast),color var(--transition-fast),border-color var(--transition-fast)}
.user-menu-footer .user-menu-logout i{color:inherit}
.user-menu-footer .user-menu-logout:hover,.user-menu-footer .user-menu-logout:focus-visible{background-color:var(--danger-color);border-color:var(--danger-color);color:#fff}
.user-menu-footer .user-menu-logout:hover i,.user-menu-footer .user-menu-logout:focus-visible i{color:#fff}
.notifications-dropdown .dropdown-toggle:after,.notification-dropdown .dropdown-toggle:after{display:none!important}
.notifications-dropdown .header-action,.notifications-mobile-btn{overflow:visible}
.notifications-dropdown .header-badge,.notifications-mobile-btn .header-badge{top:-5px;right:-5px;min-width:18px;height:18px;padding:0 5px;font-size:.62rem;font-weight:700;line-height:15px;border:1.5px solid var(--surface-color);box-shadow:0 2px 6px color-mix(in srgb,var(--danger-color),transparent 45%);z-index:2;pointer-events:none}
@keyframes headerNotifPulse{0%{box-shadow:0 0 0 0 color-mix(in srgb,var(--danger-color),transparent 35%)}70%{box-shadow:0 0 0 6px transparent}100%{box-shadow:0 0 0 0 transparent}}
.notifications-dropdown .header-badge.is-active,.notifications-mobile-btn .header-badge.is-active{animation:headerNotifPulse 2.4s infinite}
/* XivigAdmin Top-Left Brand & Toggle Refinement */
.header-left{display:flex;align-items:center;gap:14px;min-width:0}
.header-brand{display:inline-flex;align-items:center;gap:10px;min-width:0;text-decoration:none}
.header-logo{width:34px;height:34px;border-radius:10px;background:linear-gradient(135deg,#6366f1 0%,#8b5cf6 60%,#ec4899 100%);color:#fff;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;box-shadow:0 4px 12px rgba(99,102,241,.28)}
.header-context{display:inline-flex;align-items:center;gap:8px;min-width:0;line-height:1.1}
.header-context-title{font-family:var(--heading-font);color:var(--heading-color);font-size:1.08rem;font-weight:800;letter-spacing:-.025em;white-space:nowrap;overflow:visible}
.header-context-title .brand-gradient{margin-left:1px}
.header-left .badge-elite,.fauth-brand-text .badge-elite{font-family:var(--heading-font);font-size:.6rem;font-weight:700;letter-spacing:.08em;line-height:1;padding:4px 8px;border-radius:9999px;background:linear-gradient(135deg,#6366f1 0%,#8b5cf6 100%);color:#fff!important;box-shadow:0 2px 6px rgba(99,102,241,.26);flex-shrink:0}
.fauth-brand-text{display:inline-flex;align-items:center;gap:10px}
.header-left .sidebar-toggle{width:34px;height:34px;border-radius:10px;border:1px solid color-mix(in srgb,var(--border-color),transparent 10%);background:var(--surface-color);color:var(--muted-color);display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;margin-left:2px;transition:all var(--transition-fast)}
.header-left .sidebar-toggle:hover{border-color:color-mix(in srgb,var(--accent-color),transparent 45%);background:color-mix(in srgb,var(--accent-color),transparent 93%);color:var(--accent-color)}
.header-left .menu-lines{width:15px;gap:3.5px}
.header-left .menu-lines span{height:1.8px;border-radius:9999px}